def parse_duration(text):
    """Parse a compact duration such as '1h30m' into whole seconds."""
    units = {"s": 1, "m": 60, "h": 3600, "d": 86400}
    total = 0
    pending = ""
    for ch in text:
        if ch.isdigit():
            pending += ch
        else:
            total += int(pending) * units[ch]
            pending = ""
    return total

def parse_retry_after(headers):
    """Seconds a client should wait, read from a Retry-After header."""
    raw = str(headers.get("Retry-After", "0")).strip()
    if raw.isdigit():
        return int(raw)
    when = parsedate_to_datetime(raw)
    delta = when - datetime.now(timezone.utc)
    return max(0, int(delta.total_seconds()))

def chunk(seq, size):
    """Split a sequence into consecutive blocks of `size`."""
    if size <= 0:
        raise ValueError("size must be positive")
    out = []
    for i in range(0, len(seq), size):
        out.append(seq[i:i + size])
    return out

def flatten(nested):
    """Flatten arbitrarily nested lists into a single list."""
    out = []
    for item in nested:
        if isinstance(item, list):
            out.extend(flatten(item))
        else:
            out.append(item)
    return out

def merge_intervals(intervals):
    """Merge overlapping [start, end] intervals."""
    if not intervals:
        return []
    ordered = sorted(intervals)
    merged = [list(ordered[0])]
    for start, end in ordered[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return [tuple(pair) for pair in merged]

def slugify(text):
    """Turn arbitrary text into a url-safe slug."""
    out = []
    for ch in text.lower():
        if ch.isalnum():
            out.append(ch)
        else:
            if out and out[-1] != "-":
                out.append("-")
    return "".join(out).strip("-")

def clamp(value, low, high):
    """Force a value into the inclusive range [low, high]."""
    return max(low, min(high, value))

def mean(values):
    """Arithmetic mean of a list of numbers."""
    if not values:
        return 0.0
    return sum(values) / len(values)
